// door, because nothing is stored for a combined entitlement that a new window
// could orphan.
func (q *Queries) SetCombinedEntitlementWindow(ctx context.Context, arg SetCombinedEntitlementWindowParams) error {
	_, err := q.db.Exec(ctx, setCombinedEntitlementWindow,
		arg.ResetPeriod,
		arg.ResetAnchor,
		arg.ID,
		arg.OrganizationID,
	)
	return err
}

const updateEntitlement = `-- name: UpdateEntitlement :one
UPDATE entitlement e
SET name               = $1,
    description        = $2,
    icon               = $3,
    unit_singular      = $4,
    unit_plural        = $5,
    sale_unit_singular = $6,
    sale_unit_plural   = $7,
    sale_unit_factor   = $8,
    user_facing        = $9,
    display_order      = $10,
    warning_threshold_percent = $11,
    reset_period       = COALESCE(e.reset_period, $12),
    reset_anchor       = COALESCE(e.reset_anchor, $13),
    updated_at         = now()
WHERE e.slug = $14
  AND e.organization_id = $15
RETURNING e.id, e.name, e.slug, e.description, e.type, e.aggregation_method, e.organization_id, e.icon, e.unit_singular, e.unit_plural, e.sale_unit_singular, e.sale_unit_plural, e.sale_unit_factor, e.user_facing, e.display_order, e.warning_threshold_percent, e.reset_period, e.reset_anchor, e.created_at, e.updated_at, e.usage_source
`

type UpdateEntitlementParams struct {
	Name                    string                  `json:"name"`
	Description             *string                 `json:"description"`
	Icon                    *string                 `json:"icon"`
	UnitSingular            *string                 `json:"unit_singular"`
	UnitPlural              *string                 `json:"unit_plural"`
	SaleUnitSingular        *string                 `json:"sale_unit_singular"`
	SaleUnitPlural          *string                 `json:"sale_unit_plural"`
	SaleUnitFactor          *float64                `json:"sale_unit_factor"`
	UserFacing              bool                    `json:"user_facing"`
	DisplayOrder            int32                   `json:"display_order"`
	WarningThresholdPercent int16                   `json:"warning_threshold_percent"`
	ResetPeriod             *EntitlementResetPeriod `json:"reset_period"`
	ResetAnchor             *EntitlementResetAnchor `json:"reset_anchor"`
	Slug                    string                  `json:"slug"`
	OrganizationID          uuid.UUID               `json:"organization_id"`
}

// reset_period/reset_anchor are a one-way door (see the entitlement schema
// package's immutability check, enforced before this query runs): COALESCE
// means the SET is only ever effective the first time, when the stored
// value is still NULL -- once set, this UPDATE can never change it again,
// even defensively if a caller somehow bypassed the application check.
func (q *Queries) UpdateEntitlement(ctx context.Context, arg UpdateEntitlementParams) (Entitlement, error) {
	row := q.db.QueryRow(ctx, updateEntitlement,
		arg.Name,
		arg.Description,
		arg.Icon,
		arg.UnitSingular,
		arg.UnitPlural,
		arg.SaleUnitSingular,
		arg.SaleUnitPlural,
		arg.SaleUnitFactor,
		arg.UserFacing,
		arg.DisplayOrder,
		arg.WarningThresholdPercent,
		arg.ResetPeriod,
		arg.ResetAnchor,
		arg.Slug,
		arg.OrganizationID,
	)
	var i Entitlement
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.Slug,
		&i.Description,
		&i.Type,
		&i.AggregationMethod,
		&i.OrganizationID,
		&i.Icon,
		&i.UnitSingular,
		&i.UnitPlural,
		&i.SaleUnitSingular,
		&i.SaleUnitPlural,
		&i.SaleUnitFactor,
		&i.UserFacing,
		&i.DisplayOrder,
		&i.WarningThresholdPercent,
		&i.ResetPeriod,
		&i.ResetAnchor,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.UsageSource,
	)
	return i, err
}
